-- =====================================================================
-- 02_synthetic_map.sql
-- STEP 1: a synthetic campus (roads, zones, stops, routes, timetable,
--         vehicles, drivers) generated by SQL, plus verification queries.
--
-- Run in : pgAdmin 4 > Query Tool on the NEW campus_shuttle database,
--          AFTER campus_shuttle_v2_schema.sql.
-- Changes: small schema additions (PART A) and inserts (PARTS B-F).
--          Nothing is deleted. Rerunning is safe: PART A is IF NOT EXISTS
--          and every insert below is skipped when the data is already there.
-- Order  : run PART A first, then B ... G, one part at a time.
--
-- The map is ~2.6 km x 2.0 km: a 6 x 5 grid of road junctions, with
-- deterministic jitter so roads are not perfectly straight, three removed
-- links so it is not a plain grid, and 12 stops placed on junctions.
-- Every row is labelled data_source = 'simulated'.
-- =====================================================================


-- =====================================================================
-- PART A: schema additions needed by the derivation logic
-- =====================================================================

-- True when the planned offsets were typed in (e.g. from a published
-- timetable) and must NOT be overwritten by derived values.
ALTER TABLE public.route_stops
    ADD COLUMN IF NOT EXISTS offsets_entered boolean NOT NULL DEFAULT false;

-- The ordered road segments of each route (a route can share roads with others).
CREATE TABLE IF NOT EXISTS public.route_segments (
    route_id         integer NOT NULL REFERENCES public.routes(route_id) ON DELETE CASCADE,
    seq              integer NOT NULL CHECK (seq > 0),
    road_id          integer NOT NULL REFERENCES public.road_segments(road_id),
    reversed         boolean NOT NULL,                     -- travelled target -> source
    start_measure_m  numeric(10,2) NOT NULL CHECK (start_measure_m >= 0),
    end_measure_m    numeric(10,2) NOT NULL,
    PRIMARY KEY (route_id, seq),
    CONSTRAINT chk_route_segments_measures CHECK (end_measure_m > start_measure_m)
);
CREATE INDEX IF NOT EXISTS idx_route_segments_road ON public.route_segments (road_id);
COMMENT ON TABLE public.route_segments IS
 'role=STATIC-STRUCTURE; spatial=yes; temporal=no. Ordered road segments of each route with cumulative distance (derived).';

-- Metric CRS used for distances along routes. 32644 = UTM zone 44N, which
-- covers Hyderabad (~78.3 E). Change it if you relocate the synthetic campus.
INSERT INTO public.service_params (param_key, param_value, unit, description)
VALUES ('metric_srid', 32644, 'EPSG', 'Projected CRS used for metre-based measures along routes')
ON CONFLICT (param_key) DO NOTHING;

-- Junctions of the road network, derived from segment endpoints.
CREATE OR REPLACE VIEW public.v_road_nodes AS
SELECT DISTINCT ON (node_id) node_id, geom
FROM (
    SELECT source_node AS node_id, ST_StartPoint(geom) AS geom
    FROM public.road_segments WHERE source_node IS NOT NULL
    UNION ALL
    SELECT target_node, ST_EndPoint(geom)
    FROM public.road_segments WHERE target_node IS NOT NULL
) q
ORDER BY node_id;

-- Verify: route_segments exists and metric_srid is configured
SELECT (SELECT count(*) FROM information_schema.tables
        WHERE table_schema='public' AND table_name='route_segments') AS route_segments_exists,
       (SELECT param_value FROM public.service_params WHERE param_key='metric_srid') AS metric_srid;


-- =====================================================================
-- PART B: roads (46 segments)
-- Junction (i,j) has node_id = j*6 + i + 1, i in 0..5 (east), j in 0..4 (north).
-- Each segment is a 5-vertex curve between two junctions; endpoints match
-- the junction coordinates exactly.
-- =====================================================================
WITH nodes AS (
    SELECT j * 6 + i + 1 AS node_id, i, j,
           78.3200 + i * 0.0050 + 0.0007 * sin(i * 7.1 + j * 3.3) AS lon,
           17.4400 + j * 0.0045 + 0.0005 * cos(i * 5.3 + j * 2.1) AS lat
    FROM generate_series(0, 5) i CROSS JOIN generate_series(0, 4) j
), edges AS (
    SELECT a.node_id AS s, b.node_id AS t, 'h'::text AS kind
    FROM nodes a JOIN nodes b ON b.j = a.j AND b.i = a.i + 1
    UNION ALL
    SELECT a.node_id, b.node_id, 'v'
    FROM nodes a JOIN nodes b ON b.i = a.i AND b.j = a.j + 1
)
INSERT INTO public.road_segments
       (road_name, highway_class, oneway, speed_limit_kmh, geom, source_node, target_node, data_source)
SELECT CASE WHEN e.kind = 'h' THEN 'East-West Road ' || (a.j + 1)
            ELSE 'North-South Road ' || (a.i + 1) END,
       CASE WHEN (e.kind = 'v' AND a.i IN (0, 5)) OR (e.kind = 'h' AND a.j IN (0, 4))
            THEN 'secondary' ELSE 'tertiary' END,
       false,
       CASE WHEN (e.kind = 'v' AND a.i IN (0, 5)) OR (e.kind = 'h' AND a.j IN (0, 4))
            THEN 30 ELSE 25 END,
       ST_SetSRID(ST_MakeLine(ST_MakePoint(
           CASE k WHEN 0 THEN a.lon WHEN 4 THEN b.lon
                  ELSE a.lon + (b.lon - a.lon) * k / 4.0
                       - (b.lat - a.lat) * (0.08 * sin(e.s * 1.7 + e.t * 0.9)) * sin(pi() * k / 4.0) END,
           CASE k WHEN 0 THEN a.lat WHEN 4 THEN b.lat
                  ELSE a.lat + (b.lat - a.lat) * k / 4.0
                       + (b.lon - a.lon) * (0.08 * sin(e.s * 1.7 + e.t * 0.9)) * sin(pi() * k / 4.0) END
       ) ORDER BY k), 4326),
       e.s, e.t, 'simulated'
FROM edges e
JOIN nodes a ON a.node_id = e.s
JOIN nodes b ON b.node_id = e.t
CROSS JOIN generate_series(0, 4) k
WHERE (e.s, e.t) NOT IN ((22, 23), (11, 17), (8, 9))      -- three links removed
  AND NOT EXISTS (SELECT 1 FROM public.road_segments)       -- skip if already loaded
GROUP BY e.s, e.t, e.kind, a.i, a.j;

-- Verify: expect 46 roads
SELECT count(*) AS roads FROM public.road_segments;


-- =====================================================================
-- PART C: campus zones (8 rectangles)
-- =====================================================================
INSERT INTO public.campus_zones (zone_name, zone_type, boundary, data_source)
SELECT z.name, z.ztype,
       ST_Multi(ST_MakeEnvelope(z.x1, z.y1, z.x2, z.y2, 4326)), 'simulated'
FROM (VALUES
    ('Main Gate Area',      'gate',        78.3185, 17.4385, 78.3265, 17.4425),
    ('Administrative Zone', 'service',     78.3290, 17.4385, 78.3365, 17.4470),
    ('Academic Core',       'academic',    78.3235, 17.4485, 78.3365, 17.4555),
    ('Hostel West',         'residential', 78.3185, 17.4535, 78.3225, 17.4620),
    ('Hostel East',         'residential', 78.3410, 17.4535, 78.3485, 17.4620),
    ('Sports Grounds',      'sports',      78.3410, 17.4440, 78.3490, 17.4500),
    ('Lake Belt',           'forest',      78.3180, 17.4440, 78.3225, 17.4500),
    ('Faculty and Health',  'residential', 78.3385, 17.4385, 78.3490, 17.4425)
) AS z(name, ztype, x1, y1, x2, y2)
WHERE NOT EXISTS (SELECT 1 FROM public.campus_zones);

-- Verify: expect 8
SELECT count(*) AS zones FROM public.campus_zones;


-- =====================================================================
-- PART D: stops (12), placed exactly on junctions
-- =====================================================================
INSERT INTO public.stops (stop_code, stop_name, location, data_source)
SELECT s.code, s.name, n.geom, 'simulated'
FROM (VALUES
    ('S01', 'Main Gate',        1),
    ('S02', 'Admin Block',      3),
    ('S03', 'Student Centre',  10),
    ('S04', 'Central Library', 15),
    ('S05', 'Academic Block A',20),
    ('S06', 'Academic Block B',22),
    ('S07', 'Hostel West',     25),
    ('S08', 'Hostel East',     30),
    ('S09', 'Sports Complex',  18),
    ('S10', 'Health Centre',    5),
    ('S11', 'Faculty Housing',  6),
    ('S12', 'Lake View',       13)
) AS s(code, name, node_id)
JOIN public.v_road_nodes n ON n.node_id = s.node_id
WHERE NOT EXISTS (SELECT 1 FROM public.stops);

-- Verify: expect 12 stops, each at distance 0 from its junction
SELECT count(*) AS stops FROM public.stops;


-- =====================================================================
-- PART E: routes (5 forward + 5 return) and their ordered stops
-- Only the stop ORDER is entered. Route lines, segments, distances and
-- planned times are derived later by triggers (file 03).
-- =====================================================================
INSERT INTO public.routes (route_code, route_name, data_source)
SELECT r.code, r.name, 'simulated'
FROM (VALUES
    ('R1', 'Hostel West - Academic Block B'),
    ('R2', 'Main Gate - Academic Block B'),
    ('R3', 'Hostel East - Main Gate'),
    ('R4', 'Faculty Housing - Health Centre Outer Loop'),
    ('R5', 'Lake View - Central Library'),
    ('R1R','Academic Block B - Hostel West'),
    ('R2R','Academic Block B - Main Gate'),
    ('R3R','Main Gate - Hostel East'),
    ('R4R','Health Centre - Faculty Housing Outer Loop'),
    ('R5R','Central Library - Lake View')
) AS r(code, name)
WHERE NOT EXISTS (SELECT 1 FROM public.routes);

-- Forward routes: stop codes in order. Return routes are the same list reversed.
WITH fwd(route_code, stop_codes) AS (VALUES
    ('R1', ARRAY['S07','S05','S04','S06']),
    ('R2', ARRAY['S01','S02','S03','S04','S06']),
    ('R3', ARRAY['S08','S09','S03','S02','S01']),
    ('R4', ARRAY['S11','S09','S08','S06','S04','S03','S10']),
    ('R5', ARRAY['S12','S07','S05','S04'])
), expanded AS (
    SELECT route_code, code, ord::int AS seq, array_length(stop_codes, 1) AS n
    FROM fwd, unnest(stop_codes) WITH ORDINALITY AS u(code, ord)
), both_dirs AS (
    SELECT route_code AS rc, code, seq FROM expanded
    UNION ALL
    SELECT route_code || 'R', code, n + 1 - seq FROM expanded
)
INSERT INTO public.route_stops (route_id, stop_id, stop_sequence)
SELECT r.route_id, s.stop_id, b.seq
FROM both_dirs b
JOIN public.routes r ON r.route_code = b.rc
JOIN public.stops  s ON s.stop_code  = b.code
WHERE NOT EXISTS (SELECT 1 FROM public.route_stops)
ORDER BY r.route_id, b.seq;

-- Verify: expect 10 routes, 2 x (4+5+5+7+4) = 50 route_stops
SELECT (SELECT count(*) FROM public.routes) AS routes,
       (SELECT count(*) FROM public.route_stops) AS route_stops;


-- =====================================================================
-- PART F: vehicles, drivers, timetable
-- =====================================================================
INSERT INTO public.vehicles (registration_no, vehicle_type, capacity, status)
SELECT 'SIM-' || lpad(g::text, 2, '0'),
       CASE WHEN g <= 8 THEN 'Electric Bus' ELSE 'Mini Bus' END,
       CASE WHEN g <= 8 THEN 40 ELSE 25 END,
       'Active'
FROM generate_series(1, 12) g
WHERE NOT EXISTS (SELECT 1 FROM public.vehicles);

INSERT INTO public.drivers (name, license_info)
SELECT 'Driver ' || lpad(g::text, 2, '0'), 'SIM-DL-' || lpad(g::text, 3, '0')
FROM generate_series(1, 12) g
WHERE NOT EXISTS (SELECT 1 FROM public.drivers);

-- Weekday: every 15 min in the morning and evening peaks, every 30 min between.
-- Saturday: every 45 min, 09:00-15:00. Each route is staggered by 3 minutes per
-- route number, and return routes by a further 7 minutes.
INSERT INTO public.timetable_departures
       (route_id, day_type, departure_time, valid_from, source_doc, data_source)
SELECT r.route_id, w.day_type,
       (w.t + make_interval(mins => stagger.m))::time,
       DATE '2026-01-01', 'synthetic timetable v1', 'simulated'
FROM public.routes r
CROSS JOIN LATERAL (
    SELECT (substring(r.route_code FROM 2 FOR 1)::int - 1) * 3
           + CASE WHEN right(r.route_code, 1) = 'R' THEN 7 ELSE 0 END AS m
) stagger
CROSS JOIN LATERAL (
    SELECT 'weekday'::text AS day_type, g AS t
    FROM generate_series(TIMESTAMP '2000-01-01 08:00', TIMESTAMP '2000-01-01 09:59:59', interval '15 min') g
    UNION ALL
    SELECT 'weekday', g
    FROM generate_series(TIMESTAMP '2000-01-01 10:00', TIMESTAMP '2000-01-01 15:59:59', interval '30 min') g
    UNION ALL
    SELECT 'weekday', g
    FROM generate_series(TIMESTAMP '2000-01-01 16:00', TIMESTAMP '2000-01-01 17:59:59', interval '15 min') g
    UNION ALL
    SELECT 'saturday', g
    FROM generate_series(TIMESTAMP '2000-01-01 09:00', TIMESTAMP '2000-01-01 14:59:59', interval '45 min') g
) w
WHERE NOT EXISTS (SELECT 1 FROM public.timetable_departures);

-- Verify: 12 vehicles, 12 drivers, 280 weekday + 80 Saturday departures
SELECT (SELECT count(*) FROM public.vehicles) AS vehicles,
       (SELECT count(*) FROM public.drivers)  AS drivers,
       (SELECT count(*) FROM public.timetable_departures WHERE day_type = 'weekday')  AS weekday_departures,
       (SELECT count(*) FROM public.timetable_departures WHERE day_type = 'saturday') AS saturday_departures;


-- =====================================================================
-- PART G: verification queries (run each separately; read the comments)
-- =====================================================================

-- G1. Road geometry sanity. Expect: srid 4326, LINESTRING, all valid, 5 vertices,
--     lengths roughly 410-620 m.
SELECT count(*)                                  AS n_roads,
       min(ST_SRID(geom))                        AS srid_min,
       max(ST_SRID(geom))                        AS srid_max,
       bool_and(ST_IsValid(geom))                AS all_valid,
       min(ST_NPoints(geom))                     AS min_vertices,
       round(min(length_m)) AS shortest_m, round(max(length_m)) AS longest_m,
       round(sum(length_m)) AS total_m
FROM public.road_segments;

-- G2. Is the network connected? Expect: reachable_nodes = total_nodes = 30.
WITH RECURSIVE reach(node_id) AS (
    SELECT 1
    UNION
    SELECT CASE WHEN r.source_node = reach.node_id THEN r.target_node ELSE r.source_node END
    FROM reach
    JOIN public.road_segments r
      ON r.source_node = reach.node_id OR r.target_node = reach.node_id
)
SELECT (SELECT count(*) FROM reach)                  AS reachable_nodes,
       (SELECT count(*) FROM public.v_road_nodes)    AS total_nodes;

-- G3. Every junction position agrees between all segments that meet there.
--     Expect: 30 rows in v_road_nodes and 0 junctions with conflicting coordinates.
SELECT count(*) AS conflicting_junctions
FROM (
    SELECT node_id
    FROM (SELECT source_node AS node_id, ST_StartPoint(geom) AS g FROM public.road_segments
          UNION ALL
          SELECT target_node, ST_EndPoint(geom) FROM public.road_segments) q
    GROUP BY node_id
    HAVING count(DISTINCT ST_AsText(g)) > 1
) bad;

-- G4. Stops sit on junctions. Expect: 12 rows, nearest_junction_m = 0.
SELECT s.stop_code, s.stop_name,
       round(ST_X(s.location)::numeric, 5) AS lon, round(ST_Y(s.location)::numeric, 5) AS lat,
       round(ST_Distance(s.location::geography, n.geom::geography)::numeric, 2) AS nearest_junction_m
FROM public.stops s
CROSS JOIN LATERAL (SELECT geom FROM public.v_road_nodes ORDER BY geom <-> s.location LIMIT 1) n
ORDER BY s.stop_code;

-- G5. Which zone contains each stop? (A stop outside every zone shows NULL; that is allowed.)
SELECT s.stop_name, z.zone_name, z.zone_type
FROM public.stops s
LEFT JOIN public.campus_zones z ON ST_Intersects(z.boundary, s.location)
ORDER BY s.stop_code;

-- G6. Route definitions are consistent. Expect: every route has contiguous
--     sequences 1..n (max_seq = n_stops, no duplicates).
SELECT r.route_code, count(*) AS n_stops, max(rs.stop_sequence) AS max_seq,
       count(DISTINCT rs.stop_sequence) AS distinct_seq
FROM public.routes r JOIN public.route_stops rs USING (route_id)
GROUP BY r.route_code ORDER BY r.route_code;

-- G7. Timetable shape. Expect a departure every 15 min at peaks, 30 off-peak.
SELECT r.route_code, d.day_type, count(*) AS departures,
       min(d.departure_time) AS first_dep, max(d.departure_time) AS last_dep
FROM public.timetable_departures d JOIN public.routes r USING (route_id)
GROUP BY r.route_code, d.day_type ORDER BY r.route_code, d.day_type;

-- G8. Provenance: everything loaded here is labelled simulated.
SELECT 'road_segments' AS tbl, data_source, count(*) FROM public.road_segments GROUP BY 2
UNION ALL SELECT 'stops', data_source, count(*) FROM public.stops GROUP BY 2
UNION ALL SELECT 'routes', data_source, count(*) FROM public.routes GROUP BY 2
UNION ALL SELECT 'campus_zones', data_source, count(*) FROM public.campus_zones GROUP BY 2;